package com.srm.creditengine.identity.api;
import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component;
@Component class JwtTokenService { private final byte[] key; JwtTokenService(@Value("${srm.jwt-secret}") String secret){key=secret.getBytes(StandardCharsets.UTF_8);} String issue(String sub,List<String> roles){long exp=Instant.now().plusSeconds(900).getEpochSecond();String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}"), p=b64("{\"sub\":\""+sub+"\",\"roles\":\""+String.join(",",roles)+"\",\"exp\":"+exp+"}");return h+"."+p+"."+sig(h+"."+p);} private String b64(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8));} private String sig(String s){try{var m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key,"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
